        bg = 0

    rows = len(grid)
    cols = len(grid[0])

    # Initialize result grid with background color
    result = [[bg] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            # Check values at current position and its horizontal mirror
            val_left = grid[r][c]
            val_right = grid[r][cols - 1 - c]

            # Determine what to place in result[r][c]
            # We want to preserve non-background values from either side to ensure symmetry
